for old,new in rename.items():
 a=D/old;b=D/new
 if a.exists():a.rename(b)
 for c in caps:
  if c.get('path')==str(a.relative_to(W)):
   c['path']=str(b.relative_to(W));c['expected_format_rejected']=True
   c['rejection_reason']='Returned general case index, not the requested judicial decision.' if old.endswith('.xml') else 'Expected PDF magic absent; response is an HTML/challenge or generic decision-index page.'
formats=[]
for c in caps:
 p=W/c['path']
 if p.exists() and c.get('sha256'):
  assert hashlib.sha256(p.read_bytes()).hexdigest()==c['sha256'],str(p)
  formats.append({'path':c['path'],'http_status':c.get('http_status'),'sha256':c['sha256'],'accepted':bool(c.get('validated_format')),'validated_format':c.get('validated_format'),'rejection_reason':c.get('rejection_reason',c.get('error'))})
 if not c.get('validated_format'):
  c['expected_format_rejected']=True
  if c['path'].endswith(('dora.html','idd.html','dora-eli.html','idd-eli.html')):c['rejection_reason']='HTTP 202 with no substantive legal article text: rejected; not a usable EU act snapshot.'
save('sources/review-p147c-p153c/captures.json',caps);save('sources/review-p147c-p153c/format-validation.json',formats)
